/**
 * Trello Node - Version 1
 * Discriminator: resource=list, operation=update
 */


interface Credentials {
  trelloApi: CredentialReference;
  trelloOAuth1Api: CredentialReference;
}

/** Update a board */
export type TrelloV1ListUpdateParams = {
  resource: 'list';
  operation: 'update';
  authentication?: 'apiKey' | 'oAuth1' | Expression<string>;
/**
 * The ID of the list to update
 */
    id: string | Expression<string>;
/**
 * Update Fields
 * @default {}
 */
    updateFields?: {
    /** ID of a board the list should be moved to
     */
    idBoard?: string | Expression<string>;
    /** Whether the list is closed
     * @default false
     */
    closed?: boolean | Expression<boolean>;
    /** New name of the list
     */
    name?: string | Expression<string>;
    /** The position of the list. top, bottom, or a positive float.
     * @default bottom
     */
    pos?: string | Expression<string>;
    /** Whether the acting user is subscribed to the list
     * @default false
     */
    subscribed?: boolean | Expression<boolean>;
  };
};

export type TrelloV1ListUpdateOutput = {
  closed?: boolean;
  id?: string;
  idBoard?: string;
  name?: string;
};

export type TrelloV1ListUpdateNode = {
  type: 'n8n-nodes-base.trello';
  version: 1;
  config: NodeConfig<TrelloV1ListUpdateParams> & { credentials?: Credentials };
  output?: Items<TrelloV1ListUpdateOutput>;
};